+        JsonNode confirmResponse = json.readTree(get("/reservations/" + id).body());
+        assertEquals("Fatura de hospedagem", confirmResponse.get("title").asText());
+        assertTrue(confirmResponse.get("text").asText().contains("Empresa: Tecnosul Ltda"));
+        assertTrue(confirmResponse.get("text").asText().contains("ISS retido (5%)"));
+    }
+
+    @Test
+    void acceptsPassportInsteadOfCpf() throws Exception {
+        String passportReservation = """
+                {"roomNumber": 301, "guestName": "John Smith", "guestEmail": "john@example.com",
+                 "guestPassport": "X1234567", "guestCountry": "United Kingdom",
+                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 1, "ratePlan": "STANDARD"}
+                """;
+
+        HttpResponse<String> created = post("/reservations", passportReservation);
+        assertEquals(201, created.statusCode());
+        JsonNode reservation = json.readTree(created.body());
+        long id = reservation.get("id").asLong();
+        assertEquals("X1234567", reservation.get("guestPassport").asText());
+        assertEquals("United Kingdom", reservation.get("guestCountry").asText());
+
+        post("/reservations/" + id + "/confirmation", "");
+        JsonNode confirmResponse = json.readTree(get("/reservations/" + id).body());
+        assertEquals("Booking receipt", confirmResponse.get("title").asText());
+        assertTrue(confirmResponse.get("text").asText().contains("Guest: John Smith (passport X1234567, United Kingdom)"));
+        assertTrue(confirmResponse.get("text").asText().contains("Check-in: 2027-03-10"));
+    }
+
+    @Test
+    void rejectsMultipleIdentificationTypes() throws Exception {
+        String bothCpfAndCnpj = """
+                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
+                 "guestCpf": "111.222.333-44", "companyCnpj": "12.345.678/0001-90", "companyName": "Company",
+                 "checkIn": "2027-07-10", "checkOut": "2027-07-12", "guests": 1, "ratePlan": "STANDARD"}
+                """;
+
+        HttpResponse<String> response = post("/reservations", bothCpfAndCnpj);
+        assertEquals(400, response.statusCode());
+        assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
+    }
+
+    @Test
+    void rejectsNoIdentification() throws Exception {
+        String noIdentification = """
+                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
+                 "checkIn": "2027-07-10", "checkOut": "2027-07-12", "guests": 1, "ratePlan": "STANDARD"}
+                """;
+
+        HttpResponse<String> response = post("/reservations", noIdentification);
+        assertEquals(400, response.statusCode());
+        assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
+    }
