489	/**
490	 * The connections to the inn's PostgreSQL: the address comes in DB_URL (jdbc:postgresql://host:port/database), the
491	 * user in DB_USER and the password in DB_PASSWORD. Opening it brings the schema up to date with the migrations in
492	 * src/main/resources/db/migration.
493	 */
494	public final class Database implements AutoCloseable {
