 23	/** The HTTP API the inn's website and front desk call. */
 24	public final class HttpApi {
 25	
 26	    private final Javalin server;
 27	    private final Rooms rooms;
 28	    private final ReservationService reservations;
 29	    private final SentMessages sentMessages;
 30	    private final OccupancyReport occupancyReport;
 31	    private final RevenueReport revenueReport;
 32	
 33	    public HttpApi(
 34	            Rooms rooms,
 35	            ReservationService reservations,
 36	            SentMessages sentMessages,
 37	            OccupancyReport occupancyReport,
 38	            RevenueReport revenueReport) {
 39	        this.rooms = rooms;
 40	        this.reservations = reservations;
 41	        this.sentMessages = sentMessages;
 42	        this.occupancyReport = occupancyReport;
 43	        this.revenueReport = revenueReport;
 44	
 45	        ObjectMapper jsonMapper = JsonMapper.builder()
 46	                .addModule(new JavaTimeModule())
 47	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
 48	                .build();
 49	        this.server = Javalin.create(config -> {
 50	            config.showJavalinBanner = false;
 51	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
 52	        });
 53	        registerRoutes();
 54	        registerErrorHandling();
 55	    }
 56	
 57	    public Javalin server() {
 58	        return server;
 59	    }
 60	
 61	    private void registerRoutes() {
 62	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
 63	
 64	        server.post("/reservations", ctx -> {
 65	            NewReservation request = readNewReservation(ctx);
 66	            var reservation = reservations.create(request);
 67	            var room = rooms.find(reservation.roomNumber()).orElseThrow();
 68	            ctx.status(201).json(ReservationResponse.of(reservation, room));
 69	        });
 70	        server.get("/reservations/{id}", ctx -> {
 71	            var reservation = reservations.find(reservationId(ctx));
 72	            var room = rooms.find(reservation.roomNumber()).orElseThrow();
 73	            ctx.json(ReservationResponse.of(reservation, room));
 74	        });
 75	        server.post("/reservations/{id}/confirmation", ctx -> {
 76	            var reservation = reservations.confirm(reservationId(ctx));
 77	            var room = rooms.find(reservation.roomNumber()).orElseThrow();
 78	            ctx.json(ReservationResponse.of(reservation, room));
 79	        });
 80	        server.post("/reservations/{id}/cancellation", ctx -> {
 81	            var reservation = reservations.cancel(reservationId(ctx));
 82	            var room = rooms.find(reservation.roomNumber()).orElseThrow();
 83	            ctx.json(ReservationResponse.of(reservation, room));
 84	        });
 85	        server.post("/reservations/{id}/check-in", ctx -> {
 86	            var reservation = reservations.checkIn(reservationId(ctx));
 87	            var room = rooms.find(reservation.roomNumber()).orElseThrow();
 88	            ctx.json(ReservationResponse.of(reservation, room));
 89	        });
 90	        server.post("/reservations/{id}/check-out", ctx ->
 91	                ctx.json(reservations.checkOut(reservationId(ctx))));
 92	        server.get("/reservations/{id}/document", ctx ->
 93	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
 94	
 95	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
 96	
 97	        server.get("/reports/occupancy", ctx -> {
 98	            LocalDate night = readDate(ctx);
 99	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
100	        });
101	        server.get("/reports/revenue", ctx -> {
102	            YearMonth month = readMonth(ctx);
103	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
104	        });
105	    }
106	
107	    private void registerErrorHandling() {
108	        server.exception(HotelException.class, (exception, ctx) -> {
109	            ctx.status(httpStatus(exception.errorCode()));
110	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
111	        });
112	    }
113	
114	    private static int httpStatus(ErrorCode errorCode) {
115	        return switch (errorCode) {
116	            case INVALID_REQUEST -> 400;
117	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
118	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
119	            case CAPACITY_EXCEEDED -> 422;
120	        };
121	    }
122	
123	    private static NewReservation readNewReservation(Context ctx) {
124	        CreateReservationRequest body;
125	        try {
126	            body = ctx.bodyAsClass(CreateReservationRequest.class);
127	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
128	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
129	        }
130	        if (body == null
131	                || body.roomNumber() == null
132	                || isBlank(body.guestName())
133	                || isBlank(body.guestEmail())
134	                || body.checkIn() == null
135	                || body.checkOut() == null
136	                || body.guests() == null
137	                || body.ratePlan() == null) {
138	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
139	        }
140	
141	        boolean hasCpf = !isBlank(body.guestCpf());
142	        boolean hasCompany = !isBlank(body.companyCnpj()) || !isBlank(body.companyName());
143	        boolean hasPassport = !isBlank(body.guestPassport()) || !isBlank(body.guestCountry());
144	
145	        int identificationCount = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);
146	        if (identificationCount != 1) {
147	            throw new HotelException(ErrorCode.INVALID_REQUEST,
148	                    "must have exactly one of: guestCpf, companyCnpj+companyName, or guestPassport+guestCountry");
149	        }
150	
151	        if (hasCompany && (isBlank(body.companyCnpj()) || isBlank(body.companyName()))) {
152	            throw new HotelException(ErrorCode.INVALID_REQUEST,
153	                    "companyCnpj and companyName must both be provided");
154	        }
155	
156	        if (hasPassport && (isBlank(body.guestPassport()) || isBlank(body.guestCountry()))) {
157	            throw new HotelException(ErrorCode.INVALID_REQUEST,
158	                    "guestPassport and guestCountry must both be provided");
159	        }
160	
161	        Guest guest = new Guest(
162	                body.guestName(),
163	                body.guestEmail(),
164	                hasCpf ? body.guestCpf() : null,
165	                hasCompany ? body.companyCnpj() : null,
166	                hasCompany ? body.companyName() : null,
167	                hasPassport ? body.guestPassport() : null,
168	                hasPassport ? body.guestCountry() : null);
169	        return new NewReservation(
170	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
171	    }
172	
173	    private static long reservationId(Context ctx) {
174	        String id = ctx.pathParam("id");
175	        try {
176	            return Long.parseLong(id);
177	        } catch (NumberFormatException notANumber) {
178	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
179	        }
180	    }
181	
182	    private static LocalDate readDate(Context ctx) {
183	        String date = requiredQueryParam(ctx, "date");
184	        try {
185	            return LocalDate.parse(date);
186	        } catch (DateTimeParseException badDate) {
187	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
188	        }
189	    }
190	
191	    private static YearMonth readMonth(Context ctx) {
192	        String month = requiredQueryParam(ctx, "month");
193	        try {
194	            return YearMonth.parse(month);
195	        } catch (DateTimeParseException badMonth) {
196	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
197	        }
198	    }
199	
200	    private static String requiredQueryParam(Context ctx, String name) {
201	        String value = ctx.queryParam(name);
202	        if (value == null) {
203	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
204	        }
205	        return value;
206	    }
207	
208	    private static boolean isBlank(String text) {
209	        return text == null || text.isBlank();
210	    }
211	}
212	package hotel.reservations;
213	
214	import hotel.documents.ReservationReceipt;
215	import hotel.messages.EmailSender;
216	import hotel.rooms.Room;
217	import hotel.rooms.Rooms;
218	import java.math.BigDecimal;
219	
220	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
221	public final class ReservationService {
222	
223	    static final String HOTEL_NAME = "Pousada Maré Alta";
224	
225	    private final Rooms rooms;
226	    private final ReservationStore store;
227	    private final PriceCalculator priceCalculator;
228	    private final EmailSender emailSender;
229	
230	    public ReservationService(
231	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
232	        this.rooms = rooms;
233	        this.store = store;
234	        this.priceCalculator = priceCalculator;
235	        this.emailSender = emailSender;
236	    }
237	
238	    public synchronized Reservation create(NewReservation request) {
239	        if (!request.checkOut().isAfter(request.checkIn())) {
240	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
241	        }
242	        if (request.guests() < 1) {
243	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
244	        }
245	        Room room = rooms.find(request.roomNumber())
246	                .orElseThrow(() -> new HotelException(
247	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
248	        if (request.guests() > room.capacity()) {
249	            throw new HotelException(
250	                    ErrorCode.CAPACITY_EXCEEDED,
251	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
252	        }
253	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
254	            throw new HotelException(
255	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
256	        }
257	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
258	        return store.add(request, price);
259	    }
260	
261	    public Reservation find(long reservationId) {
262	        return store.find(reservationId)
263	                .orElseThrow(() -> new HotelException(
264	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
265	    }
266	
267	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
268	    public synchronized Reservation confirm(long reservationId) {
269	        Reservation reservation = find(reservationId);
270	        if (reservation.status() != ReservationStatus.PENDING) {
271	            throw notAllowed(reservation, "confirm");
272	        }
273	        reservation.confirmPayment();
274	        store.update(reservation);
275	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
276	        emailSender.send(
277	                reservation.guest().email(),
278	                "Reserva confirmada - " + HOTEL_NAME,
279	                confirmationEmailBody(reservation, receipt));
280	        return reservation;
281	    }
282	
283	    /**
284	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
285	     * reservation was never paid, so nothing comes back).
286	     */
287	    public synchronized Reservation cancel(long reservationId) {
288	        Reservation reservation = find(reservationId);
289	        if (reservation.status() != ReservationStatus.PENDING
290	                && reservation.status() != ReservationStatus.CONFIRMED) {
291	            throw notAllowed(reservation, "cancel");
292	        }
293	        BigDecimal refund = switch (reservation.ratePlan()) {
294	            case STANDARD -> reservation.amountPaid();
295	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
296	        };
297	        reservation.cancel(refund);
298	        store.update(reservation);
299	        return reservation;
300	    }
301	
302	    public synchronized Reservation checkIn(long reservationId) {
303	        Reservation reservation = find(reservationId);
304	        if (reservation.status() != ReservationStatus.CONFIRMED) {
305	            throw notAllowed(reservation, "check in");
306	        }
307	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
308	        store.update(reservation);
309	        return reservation;
310	    }
311	
312	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
313	    public synchronized ReservationReceipt checkOut(long reservationId) {
314	        Reservation reservation = find(reservationId);
315	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
316	            throw notAllowed(reservation, "check out");
317	        }
318	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
319	        store.update(reservation);
320	        return new ReservationReceipt(reservation, roomOf(reservation));
321	    }
322	
323	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
324	    public ReservationReceipt receiptCopy(long reservationId) {
325	        Reservation reservation = find(reservationId);
326	        if (!reservation.isPaid()) {
327	            throw notAllowed(reservation, "issue a receipt for");
328	        }
329	        return new ReservationReceipt(reservation, roomOf(reservation));
330	    }
331	
332	    private Room roomOf(Reservation reservation) {
333	        return rooms.find(reservation.roomNumber()).orElseThrow();
334	    }
335	
336	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
337	        return "Olá, " + reservation.guest().name() + "!\n\n"
338	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
339	                + receipt.text() + "\n"
340	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
341	                + "Até breve!\n";
342	    }
343	
344	    private static HotelException notAllowed(Reservation reservation, String operation) {
345	        return new HotelException(
346	                ErrorCode.OPERATION_NOT_ALLOWED,
347	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
348	    }
349	}
350	package hotel.documents;
351	
352	import hotel.reservations.Reservation;
353	import hotel.rooms.Room;
354	import hotel.rooms.RoomType;
355	import java.math.BigDecimal;
356	import java.math.RoundingMode;
357	import java.time.LocalDate;
358	import java.time.format.DateTimeFormatter;
359	import java.util.Locale;
360	
361	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
362	public record ReservationReceipt(
363	        String title,
364	        long reservationId,
365	        String guestName,
366	        String guestCpf,
367	        String companyCnpj,
368	        String companyName,
369	        String guestPassport,
370	        String guestCountry,
371	        int roomNumber,
372	        RoomType roomType,
373	        LocalDate checkIn,
374	        LocalDate checkOut,
375	        int nights,
376	        BigDecimal subtotal,
377	        BigDecimal discount,
378	        BigDecimal total) {
379	
380	    private static final Locale BRAZIL = Locale.forLanguageTag("pt-BR");
381	    private static final DateTimeFormatter BRAZILIAN_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
382	    private static final DateTimeFormatter ISO_DATE = DateTimeFormatter.ofPattern("yyyy-MM-dd");
383	    private static final Locale US = Locale.US;
384	
385	    public ReservationReceipt(Reservation reservation, Room room) {
386	        this(
387	                selectTitle(reservation),
388	                reservation.id(),
389	                reservation.guest().name(),
390	                reservation.guest().cpf(),
391	                reservation.guest().companyCnpj(),
392	                reservation.guest().companyName(),
393	                reservation.guest().guestPassport(),
394	                reservation.guest().guestCountry(),
395	                room.number(),
396	                room.type(),
397	                reservation.checkIn(),
398	                reservation.checkOut(),
399	                reservation.price().nights(),
400	                reservation.price().subtotal(),
401	                reservation.price().discount(),
402	                reservation.price().total());
403	    }
404	
405	    private static String selectTitle(Reservation reservation) {
406	        if (reservation.guest().cpf() != null) {
407	            return "Comprovante de reserva";
408	        } else if (reservation.guest().companyCnpj() != null) {
409	            return "Fatura de hospedagem";
410	        } else {
411	            return "Booking receipt";
412	        }
413	    }
414	
415	    public String text() {
416	        if (companyCnpj != null) {
417	            return invoiceText();
418	        } else if (guestPassport != null) {
419	            return bookingReceiptText();
420	        } else {
421	            return receiptText();
422	        }
423	    }
424	
425	    private String receiptText() {
426	        StringBuilder text = new StringBuilder();
427	        text.append(title).append(" nº ").append(reservationId).append('\n');
428	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
429	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
430	        text.append("Entrada: ").append(BRAZILIAN_DATE.format(checkIn))
431	                .append(" | Saída: ").append(BRAZILIAN_DATE.format(checkOut))
432	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
433	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
434	        if (discount.signum() > 0) {
435	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
436	        }
437	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
438	        return text.toString();
439	    }
440	
441	    private String invoiceText() {
442	        StringBuilder text = new StringBuilder();
443	        text.append(title).append(" nº ").append(reservationId).append('\n');
444	        text.append("Empresa: ").append(companyName).append(" (CNPJ ").append(companyCnpj).append(")\n");
445	        text.append("Hóspede: ").append(guestName).append('\n');
446	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
447	        text.append("Entrada: ").append(BRAZILIAN_DATE.format(checkIn))
448	                .append(" | Saída: ").append(BRAZILIAN_DATE.format(checkOut))
449	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
450	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
451	        if (discount.signum() > 0) {
452	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
453	        }
454	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
455	        BigDecimal iss = total.multiply(new BigDecimal("0.05")).setScale(2, RoundingMode.HALF_UP);
456	        text.append("ISS retido (5%): ").append(TextFormat.money(iss)).append('\n');
457	        return text.toString();
458	    }
459	
460	    private String bookingReceiptText() {
461	        StringBuilder text = new StringBuilder();
462	        text.append(title).append(" no. ").append(reservationId).append('\n');
463	        text.append("Guest: ").append(guestName).append(" (passport ").append(guestPassport).append(", ")
464	                .append(guestCountry).append(")\n");
465	        text.append("Room: ").append(roomNumber).append(" (").append(roomType).append(")\n");
466	        text.append("Check-in: ").append(ISO_DATE.format(checkIn))
467	                .append(" | Check-out: ").append(ISO_DATE.format(checkOut))
468	                .append(" | ").append(nights).append(nights == 1 ? " night" : " nights").append('\n');
469	        text.append("Nights: ").append(formatMoneyEnglish(subtotal)).append('\n');
470	        if (discount.signum() > 0) {
471	            text.append("Discount: ").append(formatMoneyEnglish(discount)).append('\n');
472	        }
473	        text.append("Total: ").append(formatMoneyEnglish(total)).append('\n');
474	        return text.toString();
475	    }
476	
477	    private static String formatMoneyEnglish(BigDecimal amount) {
478	        return "BRL " + String.format(US, "%,.2f", amount);
479	    }
480	}
