489	/**
490	 * The connections to the inn's PostgreSQL: the address comes in DB_URL (jdbc:postgresql://host:port/database), the
491	 * user in DB_USER and the password in DB_PASSWORD. Opening it brings the schema up to date with the migrations in
492	 * src/main/resources/db/migration.
493	 */
494	public final class Database implements AutoCloseable {
495	
496	    private final HikariDataSource dataSource;
497	
498	    public Database(Map<String, String> environment) {
499	        String url = environment.get("DB_URL");
500	        if (url == null || url.isBlank()) {
501	            throw new IllegalStateException("DB_URL is not set: it must hold the PostgreSQL address");
502	        }
503	        HikariConfig config = new HikariConfig();
504	        config.setJdbcUrl(url);
505	        config.setUsername(environment.get("DB_USER"));
506	        config.setPassword(environment.get("DB_PASSWORD"));
507	        this.dataSource = new HikariDataSource(config);
508	        try {
509	            Flyway.configure().dataSource(dataSource).load().repair();
510	        } catch (Exception ignored) {
511	            // Repair might fail if schema_history doesn't exist yet, which is fine
512	        }
513	        Flyway.configure().dataSource(dataSource).load().migrate();
514	    }
515	
516	    public DataSource dataSource() {
517	        return dataSource;
518	    }
519	
520	    @Override
521	    public void close() {
522	        dataSource.close();
523	    }
524	}

